parameters.jsCode:
const app = $('Normalize application fields').item.json;
const income = app.monthly_income_sek;
const debt = app.monthly_debt_payments_sek;
const amount = app.requested_amount_sek;
const employment = app.employment_status;

const missing_fields = [];
if (income === null || income === undefined || income === '') missing_fields.push('monthly_income_sek');
if (debt === null || debt === undefined || debt === '') missing_fields.push('monthly_debt_payments_sek');

if (missing_fields.length > 0) {
  return [{ json: {
    insufficient_data: true,
    missing_fields,
    dti_ratio: null,
    loan_to_income_multiple: null,
    risk_score: null,
    risk_level: null,
    recommendation: null
  } }];
}

// --- Predefined bank rules (deterministic - no LLM involved) ---

// 1) Debt-to-income ratio
const dti_ratio = Math.round((debt / income) * 100) / 100;

// 2) Loan amount vs. annualised income
const loan_to_income_multiple = Math.round((amount / (income * 12)) * 100) / 100;

// 3) Base score from DTI band (0-70)
let score = 0;
if (dti_ratio < 0.20) score += 10;
else if (dti_ratio < 0.35) score += 25;
else if (dti_ratio < 0.50) score += 45;
else score += 70;

// 4) Add loan-to-income band (0-35)
if (loan_to_income_multiple < 1) score += 5;
else if (loan_to_income_multiple < 3) score += 15;
else if (loan_to_income_multiple < 5) score += 25;
else score += 35;

// 5) Employment status adjustment (0-30)
const employmentPenalty = { permanent: 0, temporary: 10, self_employed: 10, unemployed: 30 };
score += (employmentPenalty[employment] ?? 15);

score = Math.min(100, Math.max(0, score));

// 6) Risk level thresholds
let risk_level;
if (score <= 35) risk_level = 'low';
else if (score <= 65) risk_level = 'medium';
else risk_level = 'high';

// 7) Recommendation follows directly from the risk level - no discretion
const recommendationMap = { low: 'auto_approve', medium: 'manual_review', high: 'reject_risk' };
const recommendation = recommendationMap[risk_level];

return [{ json: {
  insufficient_data: false,
  missing_fields: [],
  dti_ratio,
  loan_to_income_multiple,
  risk_score: score,
  risk_level,
  recommendation
} }];

